//! Frozen vectors generated by Node/OpenSSL, not by the Rust implementation.
//! Public synthetic keys/nonces are restricted to this test module.
use super::*;

#[derive(Deserialize)]
struct Vector {
    key: String,
    seed: String,
    public_key: String,
    plaintext: String,
    aad: String,
    signed: String,
    wire: WireEnvelope,
}

fn vector() -> Vector {
    serde_json::from_str(include_str!(
        "../../../tests/fixtures/sync-envelope-v1.json"
    ))
    .unwrap()
}

#[test]
fn fixed_openssl_wire_verifies_and_decrypts_with_exact_protocol_framing() {
    let vector = vector();
    let wire = serde_json::to_vec(&vector.wire).unwrap();
    let envelope = EncryptedEnvelope::from_bytes(&wire).unwrap();
    let header = &vector.wire.header;
    let aad = header.authenticated_bytes().unwrap();
    assert_eq!(encode_hex(&aad), vector.aad);
    assert_eq!(encode_hex(&envelope.signed_bytes(&aad)), vector.signed);
    assert_eq!(envelope.to_bytes().unwrap(), wire);
    let key = ContentKey::from_bytes(decode_hex(&vector.key, 32).unwrap().try_into().unwrap());
    let public_key = decode_hex(&vector.public_key, 32)
        .unwrap()
        .try_into()
        .unwrap();
    assert_eq!(
        open(&envelope, header, &key, &public_key).unwrap(),
        vector.plaintext.as_bytes()
    );
    let mut tampered = envelope.clone();
    tampered.ciphertext[0] ^= 1;
    assert!(open(&tampered, header, &key, &public_key).is_err());
}

#[test]
fn ring_aead_and_identity_signature_match_the_independent_fixed_vector() {
    let vector = vector();
    let seed = decode_hex(&vector.seed, 32).unwrap();
    let identity = signature::Ed25519KeyPair::from_seed_unchecked(&seed).unwrap();
    assert_eq!(
        encode_hex(identity.public_key().as_ref()),
        vector.public_key
    );
    let key = ContentKey::from_bytes(decode_hex(&vector.key, 32).unwrap().try_into().unwrap());
    let nonce = decode_hex(&vector.wire.nonce, NONCE_BYTES)
        .unwrap()
        .try_into()
        .unwrap();
    let aad = vector.wire.header.authenticated_bytes().unwrap();
    let mut ciphertext = vector.plaintext.as_bytes().to_vec();
    key.aead_key()
        .unwrap()
        .seal_in_place_append_tag(
            aead::Nonce::assume_unique_for_key(nonce),
            aead::Aad::from(&aad),
            &mut ciphertext,
        )
        .unwrap();
    assert_eq!(encode_hex(&ciphertext), vector.wire.ciphertext);
    let envelope = EncryptedEnvelope {
        header: vector.wire.header,
        nonce,
        ciphertext,
        signature: [0; SIGNATURE_BYTES],
    };
    let signed = envelope.signed_bytes(&aad);
    assert_eq!(
        encode_hex(identity.sign(&signed).as_ref()),
        vector.wire.signature
    );
}
